using System;using System.IO;using System.Linq;using CircuitoStudio;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;using System.Runtime.Serialization.Json;
public class AmbSampleResult{public string File;public int Records;public List<DxfEntity> Entities;public Dictionary<string,int> Classes,Unsupported;}
class DrawingAmbTests{
 static int n;static void Check(bool value,string name){n++;if(!value)throw new Exception(name);}static void Reject(Action a,string name){bool rejected=false;try{a();}catch(InvalidDataException){rejected=true;}Check(rejected,name);}
 [STAThread]static int Main(string[] args){try{string root=Environment.GetEnvironmentVariable("CIRCUITO_AMB_FIXTURES");if(String.IsNullOrEmpty(root))root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"referencias-amb");string file=Path.Combine(root,"native-control.amb");var b=File.ReadAllBytes(file);var d=DrawingAmb.Inspect(b);var snapshots=new List<AmbSampleResult>();Action<string,AmbInspection> snapshot=(name,value)=>snapshots.Add(new AmbSampleResult{File=name,Records=value.RecordCount,Entities=value.Drawing.Entities,Classes=value.Classes,Unsupported=value.Drawing.Unsupported});snapshot("native-control.amb",d);Check(d.RecordCount==7&&d.Drawing.Entities.Count==3,"original SDK record and entity count");var l=d.Drawing.Entities.Single(e=>e.Type=="LINE");Check(l.X==-12.25&&l.Y==3.5&&l.X2==47&&l.Y2==-8.125,"native line");var c=d.Drawing.Entities.Single(e=>e.Type=="CIRCLE");Check(c.X==10&&c.Y==20&&c.Radius==4.75,"native circle");var t=d.Drawing.Entities.Single(e=>e.Type=="TEXT");Check(t.X==7&&t.Y==8&&t.Height==2.5&&t.Text=="Controle AMB","native text");foreach(string name in new[]{"native-rotated","native-small","native-aligned"}){string f=Path.Combine(root,name+".amb");var x=DrawingAmb.Inspect(f);snapshot(name+".amb",x);Check(x.RecordCount==7,"native varied count "+name);if(name=="native-rotated"){var tx=x.Drawing.Entities.Single(e=>e.Type=="TEXT");Check(tx.Text=="Proteção ação 230 V"&&Math.Abs(tx.Rotation-30)<1e-10,"ANSI text and radians to degrees");Check(x.Drawing.Entities.Single(e=>e.Type=="LINE").X==-100.125,"negative native coordinate");}if(name=="native-small"){Check(x.Drawing.Entities.Single(e=>e.Type=="CIRCLE").Radius==0.002,"small radius");Check(Math.Abs(x.Drawing.Entities.Single(e=>e.Type=="TEXT").Rotation-315)<1e-10,"normalized native negative angle");}if(name=="native-aligned")Check(!x.Drawing.CompletePreview&&x.Drawing.Unsupported.ContainsKey("TEXT")&&x.Drawing.Entities.Count==2,"nondefault alignment explicitly incomplete");x.SaveOriginal(Path.Combine(root,name+"-product.amb"));Check(File.ReadAllBytes(f).SequenceEqual(File.ReadAllBytes(Path.Combine(root,name+"-product.amb"))),"varied opaque metadata preserved "+name);}string saved=Path.Combine(root,"product-roundtrip.amb");d.SaveOriginal(saved);d.SaveOriginal(saved);Check(b.SequenceEqual(File.ReadAllBytes(saved)),"exact fullfile roundtrip");Check(File.Exists(saved+".bak"),"atomic backup");b[0]=0;d.SaveOriginal(saved);Check(File.ReadAllBytes(file).SequenceEqual(File.ReadAllBytes(saved)),"input array isolated");Reject(()=>DrawingAmb.Inspect(new byte[68]),"invalid header");Reject(()=>DrawingAmb.Inspect(File.ReadAllBytes(file).Take(780).ToArray()),"truncated record");Reject(()=>DrawingAmb.Inspect(File.ReadAllBytes(file).Take(1170).ToArray()),"truncated trailer");var bad=File.ReadAllBytes(file);bad[52]=255;Reject(()=>DrawingAmb.Inspect(bad),"inconsistent record counts");bad=File.ReadAllBytes(file);bad[40]=102;Reject(()=>DrawingAmb.Inspect(bad),"unknown class layout");if(File.Exists(Path.Combine(root,"Prototyp.amb"))){var original=DrawingAmb.Inspect(Path.Combine(root,"Prototyp.amb"));snapshot("Prototyp.amb",original);Check(original.RecordCount==22906,"original full prototype count");Check(original.Classes["BLOCK"]==203,"nested symbol blocks enumerated");Check(!original.Drawing.CompletePreview&&original.Drawing.Unsupported.ContainsKey("INSERT"),"prototype blocks reported unsupported");original.SaveOriginal(Path.Combine(root,"prototype-roundtrip.amb"));Check(File.ReadAllBytes(Path.Combine(root,"Prototyp.amb")).SequenceEqual(File.ReadAllBytes(Path.Combine(root,"prototype-roundtrip.amb"))),"all prototype metadata preserved");}using(var stream=File.Create(Path.Combine(root,"inspection-results.json")))new DataContractJsonSerializer(typeof(List<AmbSampleResult>)).WriteObject(stream,snapshots);var project=Project.CreateSample();string before=Path.Combine(root,"before-ui.circuito"),after=Path.Combine(root,"after-ui.circuito");project.Save(before);using(var form=new DrawingDxfForm(project,project.Boards[0])){form.LoadAmb(file);if(Environment.GetEnvironmentVariable("CIRCUITO_QA_VISUAL")=="1"){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(5,5);form.Show();Application.DoEvents();form.Refresh();form.Update();Check(form.PreviewError==null,form.PreviewError??"AMB preview painted");using(var image=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var g=Graphics.FromImage(image))g.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,form.ClientSize);image.Save(Path.Combine(root,"amb-preview.png"));}form.LoadAmb(Path.Combine(root,"native-aligned.amb"));form.Refresh();Application.DoEvents();Check(form.PreviewError==null,"unsupported text does not crash preview");form.Hide();}Reject(()=>form.LoadAmb(Path.Combine(root,"missing.amb")),"UI failed load rejected");}project.Save(after);Check(File.ReadAllBytes(before).SequenceEqual(File.ReadAllBytes(after)),"AMB inspection leaves electrical project unchanged");Console.WriteLine("PASS "+n+" AMB assertions");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
